def transform(grid):
    n = len(grid)
    bands = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                d = c - r
                if d in bands and bands[d] != v:
                    raise ValueError('inconsistent diagonal')
                bands[d] = v
    # Use the smallest period consistent with every observed diagonal band.
    period = next(p for p in range(1, 2*n + 1)
                  if all((d - e) % p != 0 or v == w
                         for d, v in bands.items()
                         for e, w in bands.items()))
    residue_color = {}
    for d, v in bands.items():
        residue_color[d % period] = v
    out = [row[:] for row in grid]
    for r in range(n):
        for c in range(len(grid[0])):
            key = (c - r) % period
            if key in residue_color:
                out[r][c] = residue_color[key]
    return out
